-- OPTIONAL DEMO DATA. Only use in a new, empty Qareeb database.
-- Edit the password below IN THE SUPABASE SQL EDITOR, not in a public GitHub file.
-- Use a unique password of at least 12 characters; no apostrophes.
-- It is shared by the demo accounts; change individual account passwords before real use.
BEGIN;
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions;
SELECT set_config('qareeb.demo_password', 'REPLACE_WITH_YOUR_OWN_PASSWORD', true);
DO $check$ BEGIN
  IF length(current_setting('qareeb.demo_password')) < 12 OR current_setting('qareeb.demo_password') = 'REPLACE_WITH_YOUR_OWN_PASSWORD' THEN
    RAISE EXCEPTION 'Choose your own demo password on the set_config line (at least 12 characters).';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users) THEN RAISE EXCEPTION 'Database already has users. Demo import cancelled; no data has been changed.'; END IF;
END $check$;
SELECT set_config('qareeb.demo_hash', crypt(current_setting('qareeb.demo_password'), gen_salt('bf', 10)), true);

















COMMIT;
